            '<li><b>中证500</b>：是从沪深300 之外选的中盘股，代表「中盘」</li>' +
            '</ul>' +
            '<b>这道题真正教的东西</b>：拿到一个指数名，先查两件事——<b>选股范围</b>和<b>加权方式</b>。这两件事决定了它代表谁。'
