            '中证500（中盘）+1.8%、创业板指（成长小盘）+2.4% 明显更强。\n' +
            '所以「大公司没动，中小公司涨得多」——这是结构性行情，不是全面上涨。\n\n' +
            '<b>如果结论反过来</b>（沪深300 涨 2%、创业板指跌 1%），那就是「大票拉指数、小票跌」，风格完全相反。\n\n' +
            '<b>这道题真正的门槛</b>：能不能从「三个数字」读出「风格」——而不是只读「涨还是跌」。\n' +
            '这也是经营分析里同一个动作：<b>看到总量变化，第一反应是拆结构</b>。'
