            "question": null,
            "html": "<p>常见的说法是：现金最安全，债券次之，股票风险高，黄金抗通胀，房产保值。</p><p>但如果你只记住这个排序，会遇到一个想不通的现象：</p><div class=\"ac-quote\">某一年股票跌 20%、债券也跌 5%、黄金涨 10% —— 「风险最低的债券」为什么也跌？</div><p>因为「风险高低」这个说法把五类资产压成了一维。<b>它们真正的区别是「赚的是什么钱」</b>。</p><p class=\"ac-goal\">这一课要解决的问题：<br>① 五类资产各自靠什么产生收益？<br>② 每类在什么环境下会亏？<br>③ 为什么「每样配一点」不是敷衍，而是有机制支撑的？</p>"
