            "title": "一张图：五类资产的收益来源",
            "html": "<table class=\"ac-table\"><tr><th>资产</th><th>赚的是什么钱</th><th>什么环境下会亏</th></tr><tr><td><b>现金</b>（存款/货基）</td><td>利息（时间的价格）</td><td>通胀高于利率时（实际利率为负）</td></tr><tr><td><b>债券</b></td><td>利息 + 利率下行带来的价格变动</td><td><b>利率上行</b>（价格跌）+ 发行人违约</td></tr><tr><td><b>股票</b></td><td>企业盈利增长 + 分红 + 估值变化</td><td>盈利下滑、估值收缩、或两者同时</td></tr><tr><td><b>黄金</b></td><td>不产生现金流；赚的是「别人愿意出更高价」</td><td>实际利率上行（持有黄金的机会成本变高）</td></tr><tr><td><b>房产</b></td><td>租金 + 增值（带杠杆）</td><td>租金下滑、流动性枯竭、杠杆放大跌幅</td></tr></table><div class=\"ac-callout\"><b>关键区别</b>：<b>股、债、房产都有「现金流」</b>（盈利/利息/租金），所以能算出「值多少钱」。<b>黄金没有现金流</b> —— 它的价格完全取决于别人愿意付多少，所以它更像「保险」而不是「生息资产」。</div><h4 style=\"margin:18px 0 8px\">为什么「都配一点」有机制支撑</h4><p>不是「分散降低风险」这种口号，而是：<b>它们亏钱的原因不同</b>。</p><ul><li>经济衰退时：股票容易亏，<b>债券往往涨</b>（因为央行降息）</li><li>通胀高企时：债券亏（利率上行），<b>黄金和实物资产往往涨</b></li><li>流动性危机时：<b>现金最值钱</b>，其他都在跌</li></ul><p class=\"ac-note\">这就是「相关性低」的实际含义：不是它们走势无关，而是<b>触发它们下跌的扳机不同</b>。</p>"
