            "html": "<p><b>假设</b>两个情景（数字为教学虚构，用来说明机制，不是预测）：</p><table class=\"ac-table\"><tr><th>资产</th><th>情景 A：经济衰退 + 央行降息</th><th>情景 B：高通胀 + 央行加息</th></tr><tr><td>现金</td><td>利息降，收益变薄</td><td><b>实际利率为负，变毛</b></td></tr><tr><td>债券</td><td><b>涨</b>（利率下行，价格上行）</td><td><b>跌</b>（利率上行）</td></tr><tr><td>股票</td><td>跌（盈利预期差）</td><td>跌（估值被利率压制）</td></tr><tr><td>黄金</td><td>可能涨（避险）</td><td><b>可能涨</b>（抗通胀）</td></tr><tr><td>房产</td><td>跌（需求弱、流动性差）</td><td>看名义租金能否跟上通胀</td></tr></table><h4 style=\"margin:14px 0 8px\">第 1 步：先问「这个情景下，什么在涨」</h4><p>看 A 列：只有债券确定涨。看 B 列：只有黄金比较确定。<b>两列的「赢家」不同</b> —— 这就是配置的理由。</p><h4 style=\"margin:14px 0 8px\">第 2 步：注意股票两列都跌</h4><p>这不是笔误。衰退时企业盈利差，高通胀时估值被利率压制 —— <b>股票在两个极端都可能跌</b>，它需要的是「增长 + 温和通胀」的环境。</p><h4 style=\"margin:14px 0 8px\">第 3 步：看清「现金」在两个情景都不好</h4><p>A 里利息变薄，B 里实际利率为负。<b>现金的作用不是赚钱，是「随时能用的选择权」</b> —— 这是它唯一不可替代的地方。</p><div class=\"ac-callout\"><b>这一步的产出</b>：你不再问「哪个资产最好」，而是问「我担心哪种情景，该用哪个资产对冲」。这是从「选产品」到「配结构」的转变。</div>"
