            "html": "<p>你可能会看到这样的现象：同一家公司在 A 股和港股（或美股 ADR）同时上市，<b>价格却差 30-50%</b>。</p><div class=\"ac-quote\">「同一家公司、同样的盈利，凭什么一边贵一边便宜？是不是有套利机会？」</div><p>理论上可以套利，但现实中这个价差<b>长期存在</b>。原因不在会计，在<b>制度与投资者结构</b>。</p><p class=\"ac-goal\">这一课要解决的问题：<br>① 两地最关键的制度差异是哪四条？<br>② 这些差异怎么造成「估值中枢不同」？<br>③ 买美股/中概股时，汇率和 ADR 会怎么影响我的实际收益？</p>"
