            "html": "<p><b>假设</b>（数字为教学虚构）：某公司在 A 股 30 元、港股 22 港元（约合 20 元人民币），价差约 <b>50%</b>。</p><h4 style=\"margin:14px 0 8px\">第 1 步：先排除「算错」的可能</h4><p>同一家公司，每股盈利一样。差异只能来自：<b>谁能买、用什么货币买、以及两地市场的定价习惯</b>。</p><h4 style=\"margin:14px 0 8px\">第 2 步：拆成四个来源</h4><table class=\"ac-table\"><tr><th>来源</th><th>机制</th></tr><tr><td>投资者结构</td><td>A 股散户占比高、题材偏好强 → 愿意给更高价；港股机构主导 → 更看现金流</td></tr><tr><td>流动性与资金通道</td><td>两地资金不能自由互通（有额度与门槛），套利被限制 → 价差无法被抹平</td></tr><tr><td>货币与汇率预期</td><td>用不同货币计价，汇率预期会影响相对吸引力</td></tr><tr><td>风险溢价</td><td>不同市场对同一风险的定价不同（政策风险、流动性风险）</td></tr></table><h4 style=\"margin:14px 0 8px\">第 3 步：结论不是「买便宜的那个」</h4><p>价差长期存在说明<b>市场认为两地的风险不同</b>。如果两边资金不能自由流动，这个价差就不是「套利机会」，而是<b>结构性差异</b>。</p><div class=\"ac-callout\"><b>这一步的产出</b>：看到「AH 价差」时，不再问「哪个便宜」，而是问「<b>为什么这个价差能长期存在</b>」。能回答后半个问题，才算理解了市场结构。</div>"
