            "title": "两只看起来一样的基金，三年差了 4%",
            "html": "<p>两只都跟踪同一个指数的基金，净值走势几乎一样，但持三年后总收益差了 <b>4 个百分点</b>。</p><div class=\"ac-quote\">差在哪？不在选股，在<b>费率</b>与<b>跟踪误差</b>。</div><p>基金的成本有四层，很多人只看了第一层（申购费打折）。而<b>真正持续吃收益的是后两层</b>：管理费与托管费，它们每天从净值里扣，你根本看不到。</p><p class=\"ac-goal\">这一课要解决的问题：<br>① 主动基金和指数基金，我该在什么情况下选哪个？<br>② ETF、场外联接、LOF 有什么区别？<br>③ 我怎么算出「持有一只基金一年到底被扣了多少」？</p>"
