            "type": "example",
            "title": "例题：持三年，到底被扣了多少",
            "html": "<p><b>假设</b>（数字为教学虚构）两只跟踪同一指数的基金：</p><table class=\"ac-table\"><tr><th></th><th>基金 A</th><th>基金 B</th></tr><tr><td>管理费</td><td>0.50% / 年</td><td>0.15% / 年</td></tr><tr><td>托管费</td><td>0.10% / 年</td><td>0.05% / 年</td></tr><tr><td>申购费（打折后）</td><td>0.15%（一次性）</td><td>0.15%（一次性）</td></tr><tr><td>跟踪误差</td><td>0.60% / 年</td><td>0.20% / 年</td></tr></table><h4 style=\"margin:14px 0 8px\">第 1 步：算「每年固定被扣」的部分</h4><p>A：0.50% + 0.10% = <b>0.60%/年</b>；B：0.15% + 0.05% = <b>0.20%/年</b>。<br>三年累计：A ≈ 1.8%，B ≈ 0.6%。<b>差 1.2 个百分点</b>。</p><h4 style=\"margin:14px 0 8px\">第 2 步：加上跟踪误差（隐形的第二层）</h4><p>跟踪误差是「基金没跟上指数」的那部分。A 每年落后 0.60%，B 落后 0.20%，三年再差 <b>1.2 个百分点</b>。</p><h4 style=\"margin:14px 0 8px\">第 3 步：加总</h4><p>三年总差距 ≈ 1.2%（费率）+ 1.2%（跟踪误差）= <b>2.4 个百分点</b>。如果再加申赎费率差与交易摩擦，接近题目开头说的 4%。</p><div class=\"ac-callout\"><b>这一步的产出</b>：你有了一个可复用的算法 —— <b>年化成本 = 管理费 + 托管费 + 跟踪误差</b>。这个数才是「同样跟踪一个指数，我该选哪只」的第一判断依据，而不是历史收益排名。</div>"
