            "html": "<p>你买了一款「中低风险」的债券基金，想着「稳健」。结果两个月跌了 <b>3%</b>。</p><div class=\"ac-quote\">债券不是「固定收益」吗？怎么会跌？</div><p>因为「固定」的是<b>票面利息</b>，不固定的是<b>价格</b>。债券在到期前可以在二级市场交易，价格随利率波动 —— <b>利率上行，债券价格下跌</b>。</p><p class=\"ac-goal\">这一课要解决的问题：<br>① 票面利率和到期收益率，哪个是我真正拿到的？<br>② 利率变动 1%，债券价格会变多少？<br>③ 为什么加息周期里「短债」比「长债」安全？</p>"
