            "html": "<p><b>假设</b>你持有一只久期 <b>6 年</b>的债券基金，规模 10 万元。</p><h4 style=\"margin:14px 0 8px\">情景 A：市场利率上行 0.5%</h4><p>价格变动 ≈ −6 × 0.5% = <b>−3%</b>。10 万 → 约 <b>9.7 万</b>，浮亏 3,000 元。</p><h4 style=\"margin:14px 0 8px\">情景 B：市场利率下行 1%</h4><p>价格变动 ≈ −6 × (−1%) = <b>+6%</b>。10 万 → 约 <b>10.6 万</b>，浮盈 6,000 元。</p><h4 style=\"margin:14px 0 8px\">第 3 步：换成短债会怎样</h4><p>如果换成久期 <b>1 年</b>的短债：情景 A 只跌 0.5%（500 元），情景 B 只涨 1%（1,000 元）。</p><div class=\"ac-callout\"><b>关键取舍</b>：久期长 = <b>利率下行时赚得多，上行时亏得多</b>。所以「该长还是短」取决于你对利率方向的判断，而不是「哪个收益高」。<br><b>如果你不知道利率会往哪走</b>，短久期是默认答案 —— 它牺牲的是收益弹性，换的是少犯错。</div><p class=\"ac-note\"><b>注意</b>：这是近似公式，实际还有凸性修正。但对「判断方向与量级」足够了。</p>"
