            "title": "例题：一份完整草案长什么样",
            "html": "<p><b>假设</b>（数字为教学虚构）小明：26 岁、单身、月薪 1.5 万、月必要支出 6,000、可支配 10 万、无房贷。</p><h4 style=\"margin:14px 0 8px\">第 1 步：算应急金</h4><p>必要支出 6,000/月 × 4 个月 = <b>2.4 万</b>。放货基。</p><p><i>为什么是 4 个月而不是 3 或 6</i>：他所在行业招聘周期约 2-3 个月，4 个月留有余量；单身无房贷，不需要 6 个月。</p><h4 style=\"margin:14px 0 8px\">第 2 步：留保障金</h4><p>按年保费约 3,000 元，留 <b>0.3 万</b>在单独的活期账户。</p><h4 style=\"margin:14px 0 8px\">第 3 步：近期要用的钱</h4><p>他计划 2 年后可能要付买房定金，预估 3 万 → 放 <b>短债（久期 1-2 年）</b>。<b>不能用长债，也不能放权益。</b></p><h4 style=\"margin:14px 0 8px\">第 4 步：长期增值</h4><p>剩下 10 − 2.4 − 0.3 − 3 = <b>4.3 万</b> → 权益类。这部分他可以承受 30% 的浮亏，因为 5 年内不用。</p><h4 style=\"margin:14px 0 8px\">第 5 步：写触发条件</h4><ul><li>失业超过 2 个月 → 把短债部分转为应急金</li><li>权益部分涨到占总资产 60% 以上 → 再平衡回 43%</li><li>确认 1 年内买房 → 把长期部分的 50% 移到短债</li><li>收入下降 30% 以上 → 重新算应急金月数</li></ul><div class=\"ac-callout\"><b>这份草案的价值不在比例，在四条触发条件。</b>比例可以因人而异，但「什么情况下改」是让配置变成<b>计划</b>而不是<b>感觉</b>的关键。</div>"
