            "html": "<p>关键是<b>别从「阳性的人」出发，要从「全部人」出发</b>。</p><table class=\"ac-table\"><tr><th>假设 10,000 人做筛查</th><th>真有问题</th><th>真没问题</th><th>合计</th></tr><tr><td><b>测出阳性</b></td><td>99（真阳性）</td><td><b>99（假阳性）</b></td><td><b>198</b></td></tr><tr><td>测出阴性</td><td>1（漏诊）</td><td>9,801</td><td>9,802</td></tr><tr><td>合计</td><td><b>100</b></td><td>9,900</td><td>10,000</td></tr></table><p class=\"ac-note\">前提：图景在人群中占 1%（100 人）；检测对真有问题的检出率 99%（99/100）；对没问题的误报率 1%（99/9900）。</p><div class=\"ac-callout\"><b>核心结论</b>：阳性一共有 <b>198</b> 人，其中真有问题 <b>99</b> 人 → <b>约 50%</b>。<br>「准确率 99%」和「阳性中一半是真」<b>并不矛盾</b> —— 前者说的是「每一类人里判对多少」，后者说的是「被判定为阳性的那些人里，真的占多少」。<b>分母不同。</b></div><h4 style=\"margin:18px 0 8px\">为什么罕见图景会放大假阳性</h4><p>因为健康人是<b>绝大多数</b>。即使误报率只有 1%，1% × 9,900 也是 99 人 —— 和真正的患者数量（99 人）一样多。</p><p class=\"ac-note\">人群越大、图景越罕见，<b>「健康人 × 误报率」这一项就越容易盖过真患者</b>。</p>"
