            "title": "销冠这个月掉了 30%",
            "html": "<p><b>假设</b>（数字为教学虚构）某销售连续三个月业绩第一，第四个月掉了 30%。</p><div class=\"ac-quote\">大家的判断：「他骄傲了」「他懈怠了」。<br>但还有一个可能：<b>他前三个月本来就有运气成分，现在只是回到了正常水平。</b></div><p>更麻烦的是：如果主管因此「加强管理」，第四个月之后业绩回升了，主管会认为<b>是自己的管理起了作用</b> —— 而真相可能只是又一次回归均值。</p><p class=\"ac-goal\">这一课要解决的问题：<br>① 为什么极端表现之后往往跟着回落？<br>② 怎么区分「真的变差」和「只是回归」？<br>③ 这个现象会怎么误导管理决策？</p>"
