            "title": "例题：用两个月的数字判断是「真滑」还是「回归」",
            "html": "<p><b>假设</b>某销售近 8 个月的业绩（万元，虚构）：<b>82 / 88 / 85 / 90 / 95 / 130 / 96 / 91</b>。</p><h4 style=\"margin:14px 0 8px\">第 1 步：先看整体波动，不看单点</h4><p>前 5 个月在 82-95 之间，均值约 88。第 6 个月突然 <b>130</b>，然后 96、91。</p><p>130 是个明显的<b>离群点</b> —— 它比之前所有月份高 40% 以上。</p><h4 style=\"margin:14px 0 8px\">第 2 步：判断 130 是「水平提升」还是「一次性事件」</h4><p>如果是水平提升，<b>后面的月份应该维持在 120 以上</b>。实际是 96、91，回到原有区间。</p><p>所以更合理的解释：130 那个月有一个<b>一次性因素</b>（大单、促销、客户集中下单），而不是能力跃升。</p><h4 style=\"margin:14px 0 8px\">第 3 步：所以「下滑 30%」这个说法本身就错了</h4><p>96 → 91 只跌了 5%，属于正常波动。<b>「跌 30%」是拿 130 当基准算出来的</b> —— 而 130 恰恰是最不可靠的那个数字。</p><div class=\"ac-callout\"><b>这一步的产出</b>：判断变化时，<b>先确认基准值本身可靠</b>。拿一个离群点当基准，任何后续数字看起来都像暴跌。<br>可复用的动作：<b>去掉最高与最低后再看均值</b>，或者看中位数而不是均值。</div>"
