            "html": "<p><b>假设</b>三条新闻（数字为教学虚构）：</p><table class=\"ac-table\"><tr><th>新闻</th><th>数字</th><th>样本量</th></tr><tr><td>① 某 App 次日留存提升</td><td>41% → 44%</td><td>未写，实际 300</td></tr><tr><td>② 某城市满意度提升</td><td>76% → 79%</td><td>12,000</td></tr><tr><td>③ 某功能使用率提升</td><td>2.1% → 2.4%</td><td>未写，实际 800</td></tr></table><h4 style=\"margin:14px 0 8px\">第 1 步：粗算误差</h4><p>① 300 → 1/√300 ≈ <b>±5.8%</b>；② 12,000 → ≈ <b>±0.9%</b>；③ 800 → ≈ <b>±3.5%</b>（但比例很小，实际误差更小，约 ±1%）</p><h4 style=\"margin:14px 0 8px\">第 2 步：比差值与误差</h4><p>① 差值 3 vs 误差 5.8 → <b>不能算提升</b><br>② 差值 3 vs 误差 0.9 → <b>可信</b><br>③ 差值 0.3 vs 误差约 1 → <b>不能算提升</b>（虽然百分比看起来「涨了 14%」，但那是相对变化，绝对差值太小）</p><h4 style=\"margin:14px 0 8px\">第 3 步：注意第 ③ 条的陷阱</h4><p>「2.1% → 2.4%」如果写成「<b>使用率大涨 14%</b>」，听起来非常显著。但那是<b>相对变化</b>（0.3/2.1），绝对变化只有 0.3 个百分点。</p><div class=\"ac-callout\"><b>这一步的产出</b>：两个提问动作 —— <b>①「样本量多少？」②「这是绝对变化还是相对变化？」</b>这两个问题能拆掉大部分营销话术。</div>"
