            "title": "独立变式：把一个模糊主张改写成两种条件",
            "question": "拿这句话：「做运营需要懂数据。」\n\n请回答：\n① 把它改写成<b>必要条件</b>的严格表述\n② 把它改写成<b>充分条件</b>的严格表述\n③ 这两句话哪一句更可能是真的？为什么？\n④ 如果有人反驳「我认识不懂数据的运营做得很好」，这句话能不能推翻①？",
            "placeholder": "先写两种改写，再判断哪句更真，最后回答反例的影响…",
