            "html": "<p>会议里你说：「我觉得 A 方案比 B 方案更好，因为 A 更灵活。」</p><div class=\"ac-quote\">这句话的问题不是错，是<b>无法被检验</b>。<br>「更好」指什么？「灵活」怎么度量？如果有人不同意，靠什么判断谁对？</div><p>能被检验的论证有固定结构。这一课把它拆成五段，每段回答一个问题。</p><p class=\"ac-goal\">这一课的产出：<br>① 五段结构的具体写法<br>② 一段完整的示例论证<br>③ 你自己写的一段（350 字内）</p>"
