            "type": "scene",
            "title": "新增创了新高，总用户却没涨",
            "html": "<p><b>假设</b>（数字为教学虚构）某产品本月新增用户 12 万，是历史最高。但月活总数从上月的 300 万变成了 298 万。</p><div class=\"ac-quote\">团队困惑：「新增最多，为什么总数还跌了？」<br>因为「新增」是<b>进水</b>，「总数」是<b>水位</b>。你只看进水，没看出水。</div><p>如果本月流失 14 万，那净变化是 12 − 14 = <b>−2 万</b>，与总数下跌一致。</p><p class=\"ac-goal\">这一课要解决的问题：<br>① 存量和流量到底怎么区分？<br>② 为什么「只看流量」会得出错误结论？<br>③ 什么情况下该看存量，什么情况下该看流量？</p>"
