            "type": "figure",
            "title": "一张图：浴缸模型",
            "html": "<div class=\"ac-tree\">  <div class=\"ac-node ac-node-1\"><b>进水（流入）</b><span>新增注册 / 新增付费 / 新入职。单位：人/月</span></div>  <div class=\"ac-node ac-node-2\"><b>出水（流出）</b><span>流失 / 退订 / 离职。单位：人/月</span></div>  <div class=\"ac-down\">↓ 净变化 = 流入 − 流出</div>  <div class=\"ac-node ac-node-6\"><b>水位（存量）</b><span>总用户 / 总订阅 / 在职人数。单位：人</span></div></div><div class=\"ac-callout\"><b>核心区别</b>：存量是一个<b>时点数</b>（某个时刻有多少），流量是一个<b>时期数</b>（一段时间内进出多少）。<br>两者不能直接比 —— 「新增 12 万」和「总量 298 万」单位不同、含义不同。</div><h4 style=\"margin:18px 0 8px\">什么时候看哪个</h4><table class=\"ac-table\"><tr><th>你要回答的问题</th><th>看哪个</th><th>为什么</th></tr><tr><td>现在有多少用户能变现</td><td><b>存量</b></td><td>收入来自存量，不是来自本月新增</td></tr><tr><td>增长势头好不好</td><td><b>净流量</b></td><td>新增再高，净流出就等于没增长</td></tr><tr><td>获客渠道有效吗</td><td><b>流入</b></td><td>只看进水口的表现</td></tr><tr><td>产品体验好不好</td><td><b>流出</b></td><td>留存/流失是体验的直接反映</td></tr></table><p class=\"ac-note\">最常见的错误是<b>用流量的成绩掩盖存量的恶化</b>：「本月新增创新高」这句话在净流失时也是真的。</p>"
