            "html": "<p><b>假设</b>（教学虚构）你上线了一个新的用户引导流程，目标是提升 30 日留存。</p><p>两周后，30 日留存几乎没变。团队焦虑：「是不是方案不对？再改一版？」</p><div class=\"ac-quote\">问题是：<b>30 日留存这个指标，物理上不可能在两周内反映出来</b>。<br>你要看的是 30 天后的数据，而现在才 14 天。</div><p>这类错误极常见：<b>用有延迟的指标做即时判断</b>，然后因为「没效果」而反复改，结果每次改动都在上一版还没生效时覆盖掉它 —— 最后什么都不知道。</p><p class=\"ac-goal\">这一课要解决的问题：<br>① 延迟从哪来？<br>② 看不到效果时最容易犯哪三种错？<br>③ 怎么为带延迟的措施设计判断方式？</p>"
