            "type": "example",
            "title": "例题：给一个带延迟的措施设计判断方式",
            "html": "<p>措施：把新用户引导从 5 步改成 3 步（接 lo05 的例子）。目标：降低引导流失、且 7 日留存不下降。</p><h4 style=\"margin:14px 0 8px\">第 1 步：先写清每个指标最早什么时候能看到</h4><table class=\"ac-table\"><tr><th>指标</th><th>最早可见</th><th>类型</th></tr><tr><td>引导完成率</td><td><b>当天</b></td><td>先行</td></tr><tr><td>首个关键动作完成率</td><td>1-2 天</td><td>先行</td></tr><tr><td>7 日留存</td><td>7 天</td><td>结果</td></tr><tr><td>30 日留存</td><td>30 天</td><td>结果</td></tr></table><h4 style=\"margin:14px 0 8px\">第 2 步：定「观察窗」——窗内不改</h4><p>规定：<b>上线后 7 天内不改动引导流程</b>。因为 7 日留存是核心结果指标，不到 7 天改，就永远测不出这一版的效果。</p><h4 style=\"margin:14px 0 8px\">第 3 步：先定「什么情况算失败」</h4><p>不要事后看着数字再决定。上线前就写：</p><ul><li>引导完成率上升 <b>且</b> 7 日留存不降超过 0.5 个百分点 → <b>保留</b></li><li>引导完成率上升但 7 日留存下降超过 2 个百分点 → <b>回滚</b></li><li>7 天后若数据未出全 → <b>延长观察，不新增改动</b></li></ul><div class=\"ac-callout\"><b>这一步的产出</b>：一份「事前判决书」。<br>它的价值不是预测结果，而是<b>防止你在事后用情绪重新解释数据</b>。没有事前标准，人总会为已经投入的东西找理由（这也是一种确认偏误）。</div>"
