            "html": "<p><b>假设</b>（教学虚构）某公司季度末复盘：</p><ul><li>销售部：超额完成签约额 <b>120%</b> ✅</li><li>交付部：人均交付单量提升 <b>15%</b> ✅</li><li>客服部：平均响应时长缩短 <b>30%</b> ✅</li></ul><p>但公司<b>利润率下降 8 个点</b>。三个部门都没做错，错在他们的 KPI 之间会相互挤压。</p><div class=\"ac-quote\">销售为了签约额签了低质量客户 → 交付成本上升<br>交付为了提高单量简化了流程 → 返工与投诉增加<br>客服为了缩短响应时长草草结单 → 问题没解决，二次来电上升</div><p class=\"ac-goal\">这一课要解决的问题：<br>① 什么叫局部最优？为什么它会伤害全局？<br>② 指标之间是怎么相互挤压的？<br>③ 除了「加强管控」，还有什么解法？</p>"
