            "html": "<p>你有一个真实的问题：某个指标不动，或者某个状态一直改不好。</p><div class=\"ac-quote\">大多数人的第一反应是「加大投入」。<br>但在系统里，<b>不同位置的干预，效率可以差十倍</b>。</div><p>有的位置你推一下就动，有的位置你推十下才有反应，还有的位置你推了反而更糟。</p><p>这一课把前面四课合成一个动作：<b>用存量/回路/延迟三个视角，找到那三个值得下手的位置</b>。</p><p class=\"ac-goal\">这一课的产出：<br>① 一个四步分析流程<br>② 一份完整示例<br③ 你自己问题的一份分析（含三个杠杆点与排序）</p>"
