            "html": "<p>问题：<b>每天投入 2 小时学 SQL，三个月过去，遇到新题型还是不会。</b></p><h4 style=\"margin:14px 0 8px\">第 1 步：画存量流量</h4><p>存量：<b>真正掌握、能独立做出来的题型数</b>。<br>流入：新学的题型、做对并复盘的题。<br>流出：<b>遗忘的</b>（两周不练就忘）、以为会了其实不会的（假的流入）。</p><p>关键发现：<b>流入里有一大半是「假流入」</b> —— 看懂了但做不出来，不算掌握。</p><h4 style=\"margin:14px 0 8px\">第 2 步：找回路</h4><p>正反馈：做对 → 有成就感 → 更愿意练 → 做得更好。<br>负反馈：<b>只刷同类题</b> → 遇到新题型不会 → 挫败 → 回到刷熟悉的题 → 更不会新题型。</p><p>关键发现：负反馈的核心是「<b>待在舒适区</b>」，而不是「不够努力」。</p><h4 style=\"margin:14px 0 8px\">第 3 步：看延迟</h4><p>从「换方法」到「新题型能做出来」，需要 4-8 周。<br>所以如果只换了三天方法就判断「没用」，那是判断过早。</p><h4 style=\"margin:14px 0 8px\">第 4 步：查边界</h4><p>当前考核的是「今天学了多久」，<b>成本（没真正掌握）被移出了当天决策</b> —— 学完就算完成，没人检查三天后能不能复述。</p><h4 style=\"margin:14px 0 8px\">三个杠杆点（按省力排序）</h4><table class=\"ac-table\"><tr><th>排序</th><th>杠杆点</th><th>为什么这个位置省力</th></tr><tr><td>1</td><td><b>改考核边界</b>：把「学了多久」换成「3 天后能否不看资料讲出来」</td><td>成本立刻回到当天 —— 学的时候就知道要能复述，会自然改变学习方式</td></tr><tr><td>2</td><td><b>削弱负反馈</b>：每次练习混入 1-2 道没见过的变式</td><td>直接打断「待在舒适区」这条回路，不需要增加时间</td></tr><tr><td>3</td><td><b>加强正反馈</b>：记录「新题型首次做对」的次数</td><td>让进步可见，但需要持续记录，比前两个费力</td></tr></table><p class=\"ac-note\">注意：<b>「每天多学 1 小时」没有进前三</b> —— 它是第 ④ 类动作，在结构问题没解决前，加时间只会让假流入更多。</p><div class=\"ac-callout\"><b>这份分析的价值</b>：它把「我不够努力」这个模糊结论，换成了三个可执行、可验证的动作，而且第一个动作<b>不增加任何时间投入</b>。</div>"
