            "explain": "<b>拆解的第一步永远是「确认口径」，不是「找原因」。</b>\n\n<b>为什么其他三个不对：</b><ul><li><b>「先分析原因」</b>：原因要由拆解结果推出来，先列假设会让你不自觉地去验证自己想验证的那个（确认偏误）</li><li><b>「先做乘法拆解」</b>：乘法拆解适合「已经知道是哪一块」之后用。一上来做，会得到多个同时轻微变化的因子，无法定优先级</li><li><b>「看竞品」</b>：竞品是外部归因，在自己数据没说清之前讨论它，等于放弃了可以查的部分</li></ul><b>这道题真正教的东西</b>：<b>顺序即能力。</b>面试里问「某指标跌了你怎么分析」，回答顺序（口径 → 加法 → 乘法 → 假设）本身就是评分点，比你说出多少个原因都重要。"
