            "placeholder": "先算贡献度，再做三因子敏感性估算，最后写一句话…",
            "reference": "<b>① 贡献度</b>（变化量 ÷ −100）：\n· A：−70 / −100 = <b>70%</b>\n· B：0 → <b>0%</b>\n· C：−30 / −100 = <b>30%</b>\n\n<b>② A 渠道三因子影响</b>（单因子变动、其余不变）：\n· 基准：60 万 × 2.0% × 1,200 = 1,440 万（这是 A 的上月口径，用于算比例）\n· 只改流量（60→55）：55 × 2% × 1,200 = 1,320 万 → <b>−8.3%</b>\n· 只改转化率（2.0%→1.8%）：60 × 1.8% × 1,200 = 1,296 万 → <b>−10.0%</b>\n· 只改客单价：无变化\n→ <b>转化率的影响略大于流量</b>（−10.0% vs −8.3%）\n\n<b>③ 一句话结论</b>：\n「收入跌 100 万里 70% 来自 A 渠道；A 的客单价未变，跌幅主要来自转化率（约 −10%）与流量（约 −8%）叠加，其中转化率贡献更大。下一步查 A 渠道的落地页或商品页是否有改动。」\n\n<b>这道题的真正门槛在第 ② 问</b>：能不能用「单因子变动、其余不变」的方式把影响拆开。直接把三个变化率相加是错的 —— 因子之间是相乘关系，不是相加。"
