            "html": "<p><b>假设</b>（数字为教学虚构）三个渠道各投 100 万：</p><table class=\"ac-table\"><tr><th>渠道</th><th>投放额</th><th>带来的贡献额</th><th>平均 ROI</th></tr><tr><td>A</td><td>100 万</td><td>180 万</td><td>1.8</td></tr><tr><td>B</td><td>100 万</td><td>250 万</td><td><b>2.5</b></td></tr><tr><td>C</td><td>100 万</td><td>120 万</td><td>1.2</td></tr></table><div class=\"ac-quote\">直觉：砍 ROI 最低的 C。<br>但如果要砍 C 的一半，你会损失多少？<b>不一定是一半</b> —— 因为 C 里可能有一批高价值用户，砍掉就没了。</div><p>这就是<b>平均 ROI</b> 与 <b>边际 ROI</b> 的区别。平均看的是「过去这笔钱的平均效率」，边际看的是「下一块钱会产出多少」。<b>分配决策必须用边际。</b></p><p class=\"ac-goal\">这一课要解决的问题：<br>① 平均 ROI 和边际 ROI 差在哪？<br>② 怎么用边际 ROI 决定砍哪里、加哪里？<br>③ 什么时候该停止投入一个渠道？</p>"
