            "html": "<p>季度复盘会，你有 15 分钟。你按「背景 → 过程 → 数据 → 分析 → 结论 → 建议」讲完。</p><div class=\"ac-quote\">会后老板说：「所以这季度到底怎么样？」<br>你讲了 15 分钟，但结论在第 12 分钟才出现 —— 而那时大家已经在看手机了。</div><p>更麻烦的是：如果老板只记住一句话，你希望是哪句？<b>那句话应该由你决定，而不是由他随机抓取。</b></p><p class=\"ac-goal\">这一课要解决的问题：<br>① 汇报应该按什么顺序讲？<br>② 20 页数据怎么取舍成 3 分钟？<br>③ 怎么保证「对方记住的那句」是你想让他记住的？</p>"
