            "html": "<table class=\"ac-table\"><tr><th>页</th><th>内容</th><th>必须包含</th><th>常见缺漏</th></tr><tr><td><b>第 1 页<br>现状</b></td><td>业务在什么位置</td><td>① 口径声明（指标定义、时间范围、数据来源）② 3-4 个核心数字 ③ 与目标的差距</td><td>不写口径，导致数字无法核对</td></tr><tr><td><b>第 2 页<br>归因</b></td><td>为什么是这个结果</td><td>① 拆解过程（加法/乘法）② 证据级别声明 ③ 最强反方（还有什么解释）</td><td>只给结论不给拆解过程</td></tr><tr><td><b>第 3 页<br>建议</b></td><td>下一步做什么</td><td>① 不超过 3 个动作 ② 每个动作的判定标准 ③ <b>停止条件</b> ④ 风险</td><td>没有停止条件</td></tr></table><div class=\"ac-callout\"><b>三页里最容易被省略、也最值钱的两项</b>：<br>· <b>口径声明</b>（第 1 页）—— 没有它，别人无法核对，你说的数字就只是「你说」<br>· <b>停止条件</b>（第 3 页）—— 没有它，建议就变成「只许成功不许失败」的空头支票</div>"
