              "提示 2／3：三页的缺漏是<b>三个不同性质</b>的问题，不能互相替代：第 1 页缺的是「可核对性」（口径不在，数字无法验证）；第 2 页缺的是「可复算性」（拆解不在，结论无法复现）；第 3 页缺的是「可验收性」（判定标准不在，做完也无法判断成败）。所以不能只补一处，也不是「补更多数据」能解决的 —— 数据再多，没有口径与拆解仍然没法用；图再漂亮，也不解决「结论从哪来」这个问题。",
              "提示 3／3：正确的补法是按三页各自的标准逐一补：第 1 页加口径声明（指标定义、时间范围、数据来源三要素一个不能少）；第 2 页加拆解过程（加法或乘法的具体拆法，让别人能照着复算）与证据级别声明（有没有对照、是随机还是准实验）；第 3 页把「继续优化」改成可判定动作（做什么、指标到什么值算成功），并补上停止条件（什么情况下停下来）。图表与行业分析是加分项，但都不解决这三个结构问题 —— 结构缺了，加什么都只是装饰。"
