        "title": "过滤与排序：NULL 的三种坑",
        "subtitle": "NULL 不是 0，也不是空字符串",
        "minutes": 23,
        "level": "入门",
        "prereq": "学过 sq01（执行顺序）",
        "goal": "学完你能做到：① 说清 NULL 与任何值比较的结果 ② 解释 NOT IN 遇 NULL 为什么返回空 ③ 写出正确的 NULL 过滤与排序写法",
