            "html": "<p>有人的用法是：凡事先问一句「能不能让 AI 做」。</p><div class=\"ac-quote\">结果是：能用的一天做三件，不能用的也硬交出去 ——<br>然后把三件错的结果混进两件对的里面，一起交上去了。</div><p>问题不在 AI 不行，在<b>判断标准太粗</b>。「AI 能不能做」这个问法本身就不对，因为它默认了「能做就该做」。</p><p>正确的问法是两个：<b>错了代价多大？错了能不能马上发现？</b></p><p class=\"ac-goal\">这一课要解决的问题：<br>① 用哪两个维度判断该不该交给 AI？<br>② 哪三类任务绝对不该交？<br>③ 那些「可以交但需要监督」的，怎么设计人来看？</p>"
