            "html": "<p><b>假设</b>（教学示例）你给 AI 接了 12 个工具：查天气、查汇率、读某个网页、发邮件、写数据库…</p><div class=\"ac-quote\">三个月后：3 个接口改了域名失效，2 个权限过期，4 个你忘了怎么用。<br>剩下的 3 个还在工作 —— 而那 3 个恰好是最简单的。</div><p>问题不是「工具不好」，而是<b>没分清什么值得做成工具</b>。</p><p>同样一件事，可以做成工具（AI 直接调用）、可以写成说明（AI 照步骤做）、也可以留给人手动做。<b>三种做法的成本与可靠性差别很大。</b></p><p class=\"ac-goal\">这一课要解决的问题：<br>① 三层各解决什么问题？<br>② 新能力该放进哪一层？<br>③ 做成工具的真实成本是什么？</p>"
