            "html": "<table class=\"ac-table\"><tr><th>层</th><th>是什么</th><th>适合什么</th><th>成本</th></tr><tr><td><b>MCP</b><br>（工具接口）</td><td>给 AI 一个可调用的函数：入参、出参、错误码都定死</td><td><b>高频 + 输入输出明确 + 结果确定</b>（查库、查汇率、发消息）</td><td>高：要写接口、要处理鉴权、要跟上游变更</td></tr><tr><td><b>Skill</b><br>（流程说明）</td><td>一段写给 AI 看的说明：分几步、每步怎么做、什么情况停</td><td><b>步骤固定但输入多变</b>（写周报、做数据体检、改文案）</td><td>低：写一段文字，随时改</td></tr><tr><td><b>CLI</b><br>（人来操作）</td><td>你自己在终端/界面里执行，AI 只给建议</td><td><b>低频 + 高风险 + 需要判断</b>（改生产库、发对外公告、动钱）</td><td>最低：不用建任何东西</td></tr></table><div class=\"ac-callout\"><b>选择原则（按顺序问三句）</b>：<br>① 这件事错了代价大吗？<b>大</b> → 留 CLI（人来点）<br>② 输入输出能定死吗？<b>能，且高频</b> → 做 MCP<br>③ 剩下的一律写 Skill<br><br><b>大部分人就错在第 ① 步</b>：把「改生产库」也做成了工具，因为「方便」。</div><h4 style=\"margin:18px 0 8px\">做成工具的真实成本</h4><p>不是「写一次」，而是<b>长期维护</b>：</p><ul><li>上游接口变了 → 你要改</li><li>权限/密钥过期 → 你要续</li><li>出错了要能排查 → 你要有日志</li><li>别人也要用 → 你要写文档</li></ul><p class=\"ac-note\">所以一个「一个月用两次」的能力，做成工具通常<b>不划算</b> —— 维护成本会超过它省下的时间。<b>写成 Skill 更合适：改起来只是一句话。</b></p>"
