            "type": "example",
            "title": "例题：两种输出的可信度差别",
            "html": "<p>问：「这份合同里，违约金是怎么约定的？」</p><h4 style=\"margin:14px 0 8px\">输出 A（流畅但无依据）</h4><p>「违约金通常为合同总额的 20%，在违约发生后 30 日内支付。若涉及重大违约，可能上浮至 30%。」</p><p>❌ 读起来非常专业，但<b>没有一句能核对</b>。而「通常」这个词掩盖了它在猜。</p><h4 style=\"margin:14px 0 8px\">输出 B（带证据与未知项）</h4><p>「<b>【证据】</b>第 8.2 条：『乙方逾期交付的，每逾期一日按合同总额的 0.5% 支付违约金，累计不超过合同总额的 20%。』」</p><p>「<b>【未知项】</b>① 合同未约定重大违约的额外责任 ② 未找到违约金支付时限的条款 ③ 第 12 条提到『另行协商』但未给标准」</p><p>✅ 你可以拿第 8.2 条去原文核对，也能立刻知道「重大违约」这一块是空白的。</p><div class=\"ac-callout\"><b>输出 B 的价值不在答得好，而在「边界清楚」</b>：<br>· 它给的那一条，你能验证<br>· 它没给的那几条，明确告诉你了<br>· 你因此知道下一步该做什么：<b>去问法务「重大违约怎么算」</b><br>而输出 A 会让你以为已经知道了 —— 那才是真正的风险。</div><h4 style=\"margin:18px 0 8px\">一个可复用的抽查规则</h4><p><b>随机抽 3 条证据回原文核对。</b>3 条都对 → 这份输出可以用（但仍标注来源）；有 1 条对不上 → <b>整份作废</b>，不能只删那一条。</p><p class=\"ac-note\">为什么「有一条错就整份作废」：因为错的那条说明它在这个主题上会编，而你没抽到的那些同样可能是编的。<b>抽样出一次错，等于对整批失去信任基础。</b></p>"
