            "explain": "<b>靠「加告诫」提升可靠性几乎无效，靠「改结构」才有效。</b>\n\n<b>为什么其他不对：</b><ul><li><b>「不要编造」</b>：它无法可靠地自我判断「我现在是不是在编」，这句指令没有可执行性</li><li><b>「全部复制一遍」</b>：不解决判断问题，还会超出上下文</li><li><b>「减少文档数」</b>：能提升准确率，但不改变「缺失被说成有」这个机制</li></ul><b>这道题真正教的东西</b>：<b>把「可靠性」做成结构性约束，而不是态度要求。</b>三个动作值得记住：① 允许空结果（消除编造动机）② 强制引用（让编造有成本、让验证有可能）③ 列出未命中（把「缺」变成可检查项）。"
