            "title": "一路跑到底的流程，错在最前面",
            "html": "<p><b>假设</b>（教学示例）你做了一个自动化流程：读邮件 → 提取需求 → 查数据库 → 生成回复 → 发送。</p><div class=\"ac-quote\">跑了一个月都正常。第 32 天，有一封邮件是客户投诉，<br>流程把它当成普通需求，自动回复了一段「已收到您的需求」。</div><p>问题不在流程不够聪明，在<b>它没有「停下来」的机制</b>：它只能一路跑完，不能在中途说「这一条我不确定，请人看」。</p><p>自动化的价值常常被误解成「省人力」。但它真正的价值是<b>把人放在该在的位置上</b> —— 确定的事让机器做，不确定的事停下来给人。</p><p class=\"ac-goal\">这一课要解决的问题：<br>① 一个任务该怎么拆成「可自动」与「留人」？<br>② 每步的验收标准怎么写？<br>③ 怎么设计「会停下来」的流程？</p>"
