            "reference": "<b>示例：自动整理竞品周报（不是答案）</b>\n\n<b>① 拆解</b>\n1. 抓取 3 个竞品官网更新 → 输出：页面文本\n2. 提取「有变化的段落」 → 输出：变更片段列表\n3. 分类变更类型（价格/功能/活动） → 输出：带类别的片段\n4. 对比上周记录 → 输出：新增项清单\n5. 生成周报草稿 → 输出：Markdown\n6. 发到团队群 → 输出：消息 ID\n\n<b>② 标注</b>\n· 1-2 自动（确定性高，错了容易发现：抓不到就没有输出）\n· 3 <b>自动 + 门槛</b>（分类靠判断，置信度低就标「待确认」）\n· 4 自动（对比是确定性计算）\n· 5 自动（生成草稿，代价小）\n· 6 <b>人工</b>（对外发布，不可逆）\n\n<b>③ 护栏</b>\n· 步骤 1：3 个站点都要成功；任一失败 → 只处理成功的，并在周报注明「X 站点抓取失败」\n· 步骤 3：置信度 &lt; 80% → 类别填「待确认」，不参与后续统计\n· 步骤 4：新增项 &gt; 30 条 → 暂停，疑似页面改版，转人工\n· 步骤 6：草稿先发到「待确认」频道，人确认后转发\n· 任一步失败 → <b>把已完成部分的中间结果一起交给人</b>，附失败日志\n\n<b>停下来的三个条件</b>：站点抓取全失败、新增项异常多（疑似改版）、分类大量待确认。\n\n<b>门槛在「停下来的条件」</b>：能不能给出<b>具体的数值阈值</b>（&gt;30 条、&lt;80%）而不是「异常时停下来」。前者可执行，后者等于没说。"
