            "answer": "加一条「结果为 0 或明显异常时暂停并告警」的校验，并改为先发草稿到内部频道确认",
            "explain": "<b>静默失败的对策是「可判定的边界检查」+「不可逆动作前留人」。</b>\n\n<b>为什么其他不对：</b><ul><li><b>「让模型不要生成 0」</b>：0 不是模型编的，是数据没取到。要查的是取数环节</li><li><b>「改发送时间」</b>：不解决校验缺失</li><li><b>「增加重试」</b>：如果数据源本身就是空的，重试也是 0；而且会重复花成本</li></ul><b>这道题真正教的东西</b>：<b>用「业务上不可能的值」当哨兵。</b>GMV 为 0、订单数为负、转化率大于 100% —— 这类值在真实业务里不可能出现，一旦出现就说明上游有问题。<b>把「不可能」写成断言，是最便宜也最有效的监控。</b>"
