            "reference": "<b>示例（不是答案）</b>：\n\n<b>① 单次输入</b>：约 8,000 字 → 粗估 12,000 token（中文字数 × 1.5）\n\n<b>② 实际调用量</b>：日调用 200 次，失败率约 15%，平均失败重试 2 次\n→ 名义 200 次，实际 ≈ 200 × (1 + 0.15 × 2) = <b>260 次</b>（约 1.3 倍）\n\n<b>③ 三条上限</b>\n· 单次 token 上限：15,000（超过则截断上下文，只保留最近 3 轮）\n· 重试上限：3 次，超过转人工\n· 日成本上限：按预期日成本 × 1.5 设置，超过即停并告警\n\n<b>④ 两条哨兵</b>\n· <b>返回条数为 0</b>（应当至少 1 条）→ 暂停，检查上游数据是否为空\n· <b>单次输入 token 超过 15,000</b>（说明上下文没裁）→ 暂停，打印当前上下文长度\n（也可用：转化率 &gt; 100%、订单数为负、金额为 0）\n\n<b>门槛在第 ② 问</b>：能不能意识到「重试会放大调用量」。很多人估成本只用「调用次数 × 单价」，忘了失败重试这个乘数 —— 而它常常是 1.2-1.6 倍。"
