            "html": "<p>你做了一件重复劳动的自动化，跑得挺顺。同事问：「这个怎么跑？」</p><div class=\"ac-quote\">你发现要讲清它，得从「先装什么」「密钥在哪」「第一步为什么这么写」讲起 ——<br>讲了 20 分钟，他还是不敢用。</div><p>这不是他笨，是<b>这个流程只存在于你脑子里</b>。它没有被写成「文档」，而是被写成了「一堆只有你懂为什么这么写的配置」。</p><p>这正是重复劳动的另一种浪费：<b>你做完了，但只省了你自己的时间</b>。</p><p class=\"ac-goal\">这一课的产出：<br>① 一份流程文档的六段结构<br② 一份完整示例<br③ 你自己的一件重复劳动，整理成文档</p>"
