            "html": "<table class=\"ac-table\"><tr><th>#</th><th>段落</th><th>写什么</th><th>缺了会怎样</th></tr><tr><td>1</td><td><b>任务定义</b></td><td>解决什么问题、多久做一次、现在花多少时间</td><td>别人不知道为什么要做</td></tr><tr><td>2</td><td><b>分层设计</b></td><td>哪层自动、哪层 AI、哪层留人（at02 的三层）</td><td>别人不知道该在哪一步停下来</td></tr><tr><td>3</td><td><b>人工点</b></td><td>三个留人位置 + 具体要人做什么判断</td><td>会一路跑到底</td></tr><tr><td>4</td><td><b>验收与兜底</b></td><td>每步验收标准 + 失败怎么走</td><td>错了发现不了 / 失败了不知道怎么办</td></tr><tr><td>5</td><td><b>成本上限</b></td><td>单次 / 重试 / 日上限</td><td>可能一夜烧掉十倍预算</td></tr><tr><td>6</td><td><b>失败哨兵</b></td><td>业务上不可能的值 + 触发动作</td><td>静默失败无人发现</td></tr></table><div class=\"ac-callout\"><b>一份文档写得好不好，用一句话检验</b>：<br><b>「一个没参与过的人，能不能照着它安全地跑一次？」</b><br>能 → 合格。还要你在旁边看着 → 那只是「你知道怎么做」，不是「流程可交接」。</div>"
