              "提示 3／3：所以最缺的是约束与输出格式。其他选项不对：② 任务其实说了（分析报告），虽然可以更具体但不是最缺的；③ 输入在真实使用时会贴上来，不是这句话的结构问题；③④ 都不是主因。<b>补法</b>：「输出 3 节：结论 / 三个证据 / 建议；全文 500 字内；结论用一句话，不要铺垫；面向业务负责人。」"
