            "title": "例题：给反例为什么更有效",
            "html": "<p>需求：把用户反馈归类，并且<b>不能把「建议」混进「问题」里</b>（很多人会顺手写建议）。</p><h4 style=\"margin:14px 0 8px\">只给正例</h4><div class=\"ac-quote\">输入：加载太慢，希望优化<br>输出：问题：加载超过 5 秒<br><br>输入：找不到入口，能不能放明显点<br>输出：问题：入口位置不显眼</div><p>⚠️ 大概率能学会。但遇到「强烈要求加个夜间模式」这种<b>纯建议</b>的反馈时，它可能写成「问题：缺少夜间模式」—— 把建议当成了问题。</p><h4 style=\"margin:14px 0 8px\">给正例 + 一个反例</h4><div class=\"ac-quote\">正例 1：<br>输入：加载太慢，希望优化<br>输出：问题：加载超过 5 秒<br><br>正例 2：<br>输入：找不到入口，能不能放明显点<br>输出：问题：入口位置不显眼<br><br>反例（错误示范，不要这样写）：<br>输入：强烈要求加夜间模式<br>错误输出：问题：缺少夜间模式功能<br>正确输出：问题：用户在夜间使用时反馈刺眼（这是现象）；「加夜间模式」是用户的建议，不属于问题描述。</div><p>✅ 一个反例直接把「问题 vs 建议」这条边界钉住了。</p><div class=\"ac-callout\"><b>为什么反例这么有效</b>：<br>只给正例时，模型学的是「大概长这样」；<br>给了反例，模型学的是「<b>这条线这里不能过</b>」—— 它知道了边界的<b>位置</b>，而不只是形状。<br><br><b>什么时候该给反例</b>：当你能说出「最容易犯的那个错」时。你说得出来，就说明边界存在，那就该给一个反例钉住它。</div>"
