            "html": "<p>你改了三轮，每次都说「不够好」，但说不清哪不好。它每一轮都在猜。</p><div class=\"ac-quote\">这个场景的问题不在模型，在<b>你没有验收标准</b>。<br>没有标准时，你和它都无法判断「改到位了没有」。</div><p>而验收标准不只是给你自己看的 —— <b>写进提示词里，它就成了对方的约束</b>。</p><p>比如把「写得简洁一点」换成：「全文不超过 200 字；每段不超过 3 句；删除所有形容词」—— 这三条能被检查，输出就会明显不同。</p><p class=\"ac-goal\">这一课要解决的问题：<br>① 什么样的标准算「可判定」？<br>② 标准怎么分层写（必须 / 应该 / 加分）？<br>③ 判定规则怎么定，避免下次又吵起来？</p>"
