            "type": "figure",
            "title": "一张图：可判定 vs 不可判定",
            "html": "<table class=\"ac-table\"><tr><th>不可判定（愿望）</th><th>可判定（标准）</th><th>为什么后者有效</th></tr><tr><td>「写得专业一点」</td><td>「不用形容词；每个结论后跟一个数字」</td><td>能数、能查</td></tr><tr><td>「逻辑清晰」</td><td>「结论放第一段；三段之间用『因为/但是/所以』连接」</td><td>结构能被检验</td></tr><tr><td>「覆盖全面」</td><td>「5 个维度各至少一句；缺哪个维度就写『未提及』」</td><td>能对照清单数</td></tr><tr><td>「不要太长」</td><td>「不超过 300 字」</td><td>有明确边界</td></tr></table><div class=\"ac-callout\"><b>一条判断标准</b>：<b>把这条标准念给另一个人听，他能不能独立判断「过了还是没过」？</b><br>能 → 可判定。不能 → 还只是愿望。<br><br>这个检验很重要，因为<b>只写在提示词里是不够的</b> —— 你自己也要能验收，否则「改三轮」还会继续。</div><h4 style=\"margin:18px 0 8px\">标准怎么分层：必须 / 应该 / 加分</h4><table class=\"ac-table\"><tr><th>层级</th><th>含义</th><th>不满足时</th></tr><tr><td><b>必须</b></td><td>硬条件，缺了就返回重做</td><td>直接判不合格，不进入下一步</td></tr><tr><td><b>应该</b></td><td>影响质量，但可以接受一时不达标</td><td>记录，下次改</td></tr><tr><td><b>加分</b></td><td>有更好，没有也行</td><td>不影响验收</td></tr></table><p class=\"ac-note\">不分层是最常见的错误：所有要求都写成「必须」，结果是<b>一条不满足就全盘重来</b>，或者干脆全部放松。<b>分层之后，你才知道什么该坚持、什么可以放过。</b></p>"
