            "type": "example",
            "title": "例题：给「写结论」定一套标准",
            "html": "<p>需求：把一份数据分析写成给老板的结论。</p><h4 style=\"margin:14px 0 8px\">改造前（全是愿望）</h4><div class=\"ac-quote\">「结论要清晰、有洞察、专业，能支撑决策，别太长。」</div><h4 style=\"margin:14px 0 8px\">改造后（分层可判定）</h4><p><b>【必须】（不满足则重做）</b></p><ul><li>第一句话是结论，且含「好/坏到什么程度 + 主要原因」</li><li>全文不超过 200 字</li><li>至少 2 个具体数字，且每个数字都标注来源与时间范围</li></ul><p><b>【应该】（不满足则记录）</b></p><ul><li>给出一个「下一步建议」，且建议可执行（能判断做了/没做）</li><li>指出一个「这个结论可能错在哪」</li></ul><p><b>【加分】</b></p><ul><li>用一个类比让非专业读者秒懂</li></ul><h4 style=\"margin:14px 0 8px\">再加「判定规则」</h4><div class=\"ac-callout\"><b>为什么需要判定规则</b>：标准写得再细，遇到边界还是会吵。<br>比如「至少 2 个具体数字」—— 百分比算不算数字？「约三成」算不算？<br><b>所以要给判定规则</b>：<br>· 算：带单位的数值、百分比、「3.2 倍」<br>· 不算：「三成左右」「大幅」「显著」「若干」<br><br>这样下次不用再讨论「这个算不算」。<b>判定规则的价值是「提前把争议解决掉」。</b></div>"
