              "提示 2／3：所以至少三个断言：① 该给的（「7 天」）在不在；② 该标的（到账时间那一行含「未提及」）对不对；③ 不该编的（到账时间的具体天数）有没有出现。第三条是防「它给了个看起来合理的 3-5 个工作日」。",
              "提示 3／3：其他选项的问题：① 人工判定太贵，20 条里全是人工就跑不动；③ 只查「有没有未提及」不够 —— 它可能五项都写「未提及」（那就是过度保守，也是失败）；④ 用另一个模型判断，引入了新的不确定性，而且成本更高、结果不稳定。<b>评测的原则是「能用确定性代码检查的，就不要用判断」。</b>"
