            "explain": "<b>「部分有依据」这类用例必须三向断言：该给的、该标的、不该编的。</b>\n\n<b>为什么其他不对：</b><ul><li><b>人工</b>：成本高，跑不动 20 条</li><li><b>只查「未提及」</b>：五项都写「未提及」也能通过 —— 那是过度保守，同样是失败</li><li><b>用另一个模型判断</b>：引入新的不确定性，成本更高</li></ul><b>这道题真正教的东西</b>：<b>判定要同时防「漏」和「多」。</b>只防漏（该有的有没有），会漏掉编造；只防多（不该有的有没有），会漏掉过度保守。两侧都查，这条用例才真的有用。"
