            "explain": "<b>平均 ROI 是历史，边际 ROI 是下一步 —— 决策必须用后者。</b>\n\n<b>为什么其他不对：</b><ul><li><b>「去年 2.8」</b>：过去的状态，且是平均口径，不能推断下一步</li><li><b>「直接拒绝」</b>：结论方向对，但少了诊断 —— 边际下降可能只是素材衰退，换了素材就能恢复</li><li><b>「加 20 万试一个月」</b>：用大钱验证一个已有证据的问题；小额分档测试更划算</li></ul><b>这道题真正教的东西</b>：<b>边际下降先诊断原因，再决定加减。</b>「人群饱和」要换人群，「素材衰退」要换素材，「竞争涨价」可能只能减。三种原因对应三种完全不同的动作 —— 不诊断就直接减或直接加，都是在赌。"
