            "question": "<b>假设</b>（示例数据）某渠道组合的总 GMV 是 50,000 元，来自 100 笔订单。路径分布：60 笔是「信息流 → 下单」，30 笔是「信息流 → 搜索 → 下单」，10 笔是「社群 → 下单」。\n\n请回答：\n① 按首触归因，三个渠道各分到多少？\n② 按末触归因，各分到多少？\n③ 按线性归因，各分到多少？\n④ 三种规则下，社群渠道的「归因 GMV」分别是多少？差异说明什么？",
