            "title": "例题：一份完整方案（骨架）",
            "html": "<p><b>以下为教学示例</b>（虚构数据）。</p><h4 style=\"margin:14px 0 8px\">1. 现状</h4><p><b>口径声明</b>：CAC 含媒体费 + 人力分摊 + 工具分摊；质量用 30 日留存；毛利 LTV 约 350 元。</p><table class=\"ac-table\"><tr><th>渠道</th><th>预算</th><th>新增</th><th>30留</th><th>CAC</th><th>有效 CAC</th><th>分层</th></tr><tr><td>A 信息流</td><td>20 万</td><td>4,000</td><td>8%</td><td>50</td><td>625</td><td><b>陷阱</b></td></tr><tr><td>B 搜索</td><td>15 万</td><td>1,100</td><td>35%</td><td>136</td><td><b>389</b></td><td>明星（微亏）</td></tr><tr><td>C 社群</td><td>15 万</td><td>750</td><td>45%</td><td>200</td><td><b>444</b></td><td>潜力</td></tr></table><h4 style=\"margin:14px 0 8px\">2. 诊断</h4><ul><li><b>A 是陷阱</b>：CAC 看起来最低（50），但有效 CAC 625 是三个里最高，每客亏 275 元（625 − 350）。<b>上月它拿走了 40% 预算，却贡献了最少的有效新客。</b></li><li><b>B 接近健康</b>：有效 CAC 389，略高于毛利 LTV 350，每客亏 39 元 —— 接近打平，优化空间在素材与落地页。</li><li><b>C 质最优但量小</b>：有效 CAC 444，质最好（45% 留存），瓶颈在量不在钱。</li><li><b>边际</b>：B 当前边际 1.5、C 1.8、A 0.7 → <b>A 已不该继续加</b>。</li></ul><h4 style=\"margin:14px 0 8px\">3. 方案</h4><table class=\"ac-table\"><tr><th>渠道</th><th>现预算</th><th>新预算</th><th>变化</th><th>依据</th></tr><tr><td>A 信息流</td><td>20 万</td><td><b>8 万</b></td><td>−12 万</td><td>边际 0.7 &lt; 1，每投多亏</td></tr><tr><td>B 搜索</td><td>15 万</td><td><b>32 万</b></td><td>+17 万</td><td>边际 1.5，且是唯一接近健康线的</td></tr><tr><td>C 社群</td><td>15 万</td><td><b>20 万</b></td><td>+5 万</td><td>边际 1.8 最高，但量有天花板</td></tr><tr><td><b>合计</b></td><td>50 万</td><td><b>60 万</b></td><td>+10 万</td><td>净增 10 万</td></tr></table><h4 style=\"margin:14px 0 8px\">4. 预期（用边际，不用平均）</h4><p>· A 减 12 万：按边际 0.7 计，<b>少亏</b> 12 × (1 − 0.7) = <b>+3.6 万贡献</b><br>· B 加 17 万：分档边际 1.5 / 1.3 / 1.1，加权约 1.3 → 增量贡献 ≈ <b>22 万</b><br>· C 加 5 万：边际 1.8 → 增量贡献 ≈ <b>9 万</b><br><b>总增量贡献 ≈ 34.6 万</b>，投入增加 10 万 → <b>净增约 24.6 万</b></p><p><b>综合 ROI</b>：从当前 1.9 提到约 <b>2.3</b>（因为砍掉了边际最低的那部分）。</p><h4 style=\"margin:14px 0 8px\">5. 停止条件</h4><ul><li>B 加预算后，若<b>有效 CAC 超过 450</b>（毛利 LTV 350 + 容忍 100）→ 停止加，回退到 20 万</li><li>C 加预算后，若<b>30 日留存掉到 35% 以下</b> → 说明扩量买到了低质人群，停止扩量</li><li>整体：若第二个月<b>综合 ROI 低于 1.8</b>（低于调整前）→ 判定方案失效，回滚</li></ul><h4 style=\"margin:14px 0 8px\">6. 风险</h4><p><b>最可能让方案失效的一件事</b>：搜索渠道的增量主要来自「品牌词」，而品牌词搜索量本身取决于信息流的前期种草 —— <b>砍信息流可能导致搜索的量也下降</b>。这是渠道间的隐性依赖，也是本方案最大的不确定性。</p><p><b>应对</b>：第一个月不把 A 砍到最低（保留 8 万而非归零），同时监控品牌词搜索量的变化；若搜索量随信息流下降超过 15%，说明存在依赖，需要重新评估。</p><div class=\"ac-callout\"><b>这份方案的关键在「风险」这一段</b>：<br>它没有说「市场可能变化」，而是指出了<b>渠道之间的隐性依赖</b>（信息流种草 → 搜索收割）。<br><b>这才是真实的渠道管理中最难的部分</b> —— 每个渠道的报表都是独立的，但它们在用户路径上是串联的。<br>能主动指出这一点，方案的可信度会显著提升。</div>"
